        float2 satriyaid;
        satriyaid = amzScreenNorm();
        satriyaid /= amzp_scale;
        satriyaid *= rot2m((0.0+amzp_angle)*0.0174533);
        satriyaid += float2((0.0+amzp_position.x), (0.0+amzp_position.y))*float2(-1.,1.)/500.;
        float2 scaleVec;
        scaleVec = float2(amzp_scale*amzp_stretch.x,amzp_scale*amzp_stretch.y);
