                 if (p.y > 1.0 || p.x < 0.0 || p.x > 1.0 || p.y < 0.0)
                     O = float4(0.0,0.0,0.0,0.0);
                 else
                     O = video;
             }
     amzOutput = (amzp_overdraw>0.5)?O : O * texColor.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

